SELECT 'решение не называет ни одной поверхности: закрытость множества ничем не держится' AS detail WHERE NOT EXISTS (SELECT 1 FROM project_surface_declared WHERE project_id = $1) UNION ALL SELECT d.surface || ' — названа решением ' || d.said_in || ', а гейт её не читает' FROM project_surface_declared d WHERE d.project_id = $1 AND NOT EXISTS (SELECT 1 FROM project_surface_source s WHERE s.project_id = d.project_id AND s.surface = d.surface) UNION ALL SELECT s.surface || ' — гейт её читает, а решение её не называет' FROM (SELECT DISTINCT project_id, surface FROM project_surface_source) s WHERE s.project_id = $1 AND NOT EXISTS (SELECT 1 FROM project_surface_declared d WHERE d.project_id = s.project_id AND d.surface = s.surface) ORDER BY 1
